#include <iostream>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    long long substitutes = 0, repairs = 0;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        if (x < 50) {
            substitutes++;
        } else if (x < 85) {
            repairs++;
        }
        // x >= 85: no repair needed
    }

    cout << substitutes << " " << repairs << "\n";
    return 0;
}
